# Completion of the scoped benchmark reference sets (v2). Every new row is a curator paraphrase
# (Claude, 22 Oct 2026) of a requirement stated in the case's own reference document, with a verbatim
# anchor quote. Inclusion rule: the source states a need or a decision of its own (a requirement
# sentence, a rationale, a changed obligation, a reported request). Text copied from DCAT-AP itself and
# table entries that only repeat a base obligation without a rationale are not added.
#
# fields: id, statement, locator, anchor, level (content|profile|system), problem (P1..P7),
#         origin (std|proj|exp|prac|law|tech), relation (restates_base|tightens_base|extends_base|
#         partly_base|beyond_base|not_term_level), status (requirement|proposed|deferred|open_issue),
#         atoms, overlaps, rq2 (reuse/alignment rule), note, extra (dict)

def R(id, statement, locator, anchor, level, problem, origin, relation, status='requirement', atoms=1,
      overlaps=(), rq2=False, note='', **extra):
    return dict(id=id, statement=statement, locator=locator, anchor=anchor, level=level, problem=problem,
                origin=list(origin), relation=relation, status=status, atoms=atoms, overlaps=list(overlaps),
                rq2=rq2, note=note, extra=extra)

